<template><div style="max-width:1000px;margin:35px auto;padding:20px"><n-space justify="space-between" align="center"><h2>情报来源配置</h2><n-space><n-button @click="$router.push('/vulnerabilities')">返回漏洞列表</n-button><n-button :loading="testingAll" @click="testAll">一键检测全部 RSS</n-button><n-button type="primary" @click="newSource">新增来源</n-button></n-space></n-space><n-alert type="warning" style="margin-bottom:20px">目前支持 RSS/Atom 公开 HTTPS 订阅源。适配器填 rss，备注填订阅地址。爬虫模式可选择，但目前尚未实现爬虫适配器，选择后不会执行抓取。原 9 个专用采集器也尚未迁移。</n-alert><n-card title="自动采集设置" style="margin-bottom:20px"><n-space align="center"><span>采集间隔</span><n-select v-model:value="intervalMinutes" :options="intervalOptions" style="width:180px"/><n-button type="primary" :loading="savingInterval" @click="saveInterval">保存全部配置</n-button></n-space><p style="color:#888">保存后立即生效，无需重启服务；默认每 60 分钟采集一次。</p><n-form-item label="采集时间范围"><n-select v-model:value="lookbackHours" :options="lookbackOptions" style="width:220px"/></n-form-item><n-form-item label="采集等级（勾选才采集；未知表示 RSS 未提供明确等级）"><n-checkbox-group v-model:value="allowedSeverities"><n-space><n-checkbox v-for="level in severityOptions" :key="level" :value="level" :label="level"/></n-space></n-checkbox-group></n-form-item><n-form-item label="一级关键词：命中后直接推送（英文逗号分隔）"><n-input v-model:value="whitelist" type="textarea" placeholder="Windows,Apache,Spring,CVE-2026" /></n-form-item><n-form-item label="二级关键词：人工确认后推送（英文逗号分隔）"><n-input v-model:value="reviewKeywords" type="textarea" placeholder="Siemens,Schneider Electric,Rockwell,Kubernetes,Jenkins"/></n-form-item><p style="color:#888">一级命中直接推送；二级命中进入人工审核；同时命中时一级优先。两级都留空则保持原有直接推送行为。</p></n-card><n-data-table :data="rows" :columns="columns"/><n-modal v-model:show="visible" preset="card" title="情报来源" style="max-width:540px"><n-form><n-form-item label="名称"><n-input v-model:value="form.name"/></n-form-item><n-form-item label="采集方式"><n-select v-model:value="form.adapter" :options="sourceTypes"/></n-form-item><n-form-item label="订阅 URL（RSS 时填写在此）"><n-input v-model:value="form.notes"/></n-form-item><n-form-item label="API Key（留空不修改）"><n-input v-model:value="apiKey" type="password" placeholder="可选密钥"/></n-form-item><n-form-item label="请求头名称"><n-input v-model:value="headerName" placeholder="Authorization 或 X-API-Key"/></n-form-item><n-form-item label="启用"><n-switch v-model:value="form.enabled"/></n-form-item><n-button type="primary" @click="save">保存</n-button></n-form></n-modal><Crawlers/></div></template>
<script setup>
import {ref,h,onMounted} from 'vue'
import {NButton,NSpace,NDataTable,NModal,NForm,NFormItem,NInput,NSelect,NCard,NSwitch,NAlert,NCheckbox,NCheckboxGroup,useMessage} from 'naive-ui'
import axios from 'axios'
import Crawlers from './Crawlers.vue'
const severityOptions=['严重','高危','中危','低危','未知'],allowedSeverities=ref([...severityOptions])
const lookbackHours=ref(24),lookbackOptions=[{label:'最近24小时',value:24},{label:'最近3天',value:72},{label:'最近7天',value:168},{label:'最近30天',value:720},{label:'不限制',value:0}]
const intervalMinutes=ref(60),savingInterval=ref(false),whitelist=ref(''),reviewKeywords=ref(''),testingAll=ref(false),testResults=ref({})
const intervalOptions=[15,30,60,180,360,720,1440].map(n=>({label:n<60?n+' 分钟':n/60+' 小时',value:n}))
const collectionHttp=axios.create({baseURL:'/api/v1/settings/collection'})
collectionHttp.interceptors.request.use(c=>{c.headers.Authorization='Bearer '+(localStorage.getItem('token')||'');return c})
async function loadInterval(){try{const d=(await collectionHttp.get('')).data.data;intervalMinutes.value=d.interval_minutes;whitelist.value=d.whitelist||'';reviewKeywords.value=d.review_keywords||'';lookbackHours.value=d.lookback_hours??24;allowedSeverities.value=d.allowed_severities??[...severityOptions]}catch(e){msg.error('读取采集周期失败：'+(e.response?.data?.detail||e.message))}}
async function saveInterval(){savingInterval.value=true;try{await collectionHttp.put('',{interval_minutes:intervalMinutes.value,whitelist:whitelist.value,review_keywords:reviewKeywords.value,lookback_hours:lookbackHours.value,allowed_severities:allowedSeverities.value});msg.success('自动采集设置已全部保存，无需重启')}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{savingInterval.value=false}}
const sourceTypes=[{label:'RSS / Atom（可用）',value:'rss'},{label:'网页爬虫（开发中）',value:'crawler',disabled:true}]
const apiKey=ref(''),headerName=ref('Authorization')
const msg=useMessage(),rows=ref([]),visible=ref(false),editing=ref(null),form=ref({name:'',adapter:'',notes:'',enabled:false,ai_enabled:false})
const http=axios.create({baseURL:'/api/v1/settings/sources'})
http.interceptors.request.use(c=>{c.headers.Authorization='Bearer '+(localStorage.getItem('token')||'');return c})
async function load(){try{rows.value=(await http.get('')).data.data}catch(e){msg.error(e.response?.data?.detail||e.message)}}
function newSource(){apiKey.value='';headerName.value='Authorization';editing.value=null;form.value={name:'',adapter:'',notes:'',enabled:false,ai_enabled:false};visible.value=true}
function edit(r){apiKey.value='';headerName.value='Authorization';editing.value=r.id;form.value={...r};visible.value=true}
async function save(){try{let id=editing.value;if(id)await http.put('/'+id,form.value);else id=(await http.post('',form.value)).data.data.id;if(apiKey.value)await http.put('/'+id+'/credential',{api_key:apiKey.value,header_name:headerName.value});visible.value=false;await load()}catch(e){msg.error(e.response?.data?.detail||e.message)}}
async function testAll(){testingAll.value=true;try{const d=(await axios.post('/api/v1/source-check/all',{}, {headers:{Authorization:'Bearer '+(localStorage.getItem('token')||'')}})).data.data;testResults.value=Object.fromEntries(d.map(x=>[x.id,x]));msg.success('检测完成：'+d.filter(x=>x.ok).length+'/'+d.length+' 个可用')}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{testingAll.value=false}}
async function testSource(r){const x=await http.post(`/../../source-check/${r.id}`);alert(JSON.stringify(x.data))}
async function remove(r){if(!confirm('确定删除 '+r.name+'？'))return;try{await http.delete('/'+r.id);await load()}catch(e){msg.error(e.message)}}
const columns=[{title:'来源',key:'name'},{title:'状态',key:'health',render:r=>{const x=testResults.value[r.id];return x?(x.ok?'🟢 可用（'+x.count+' 条）':'🔴 不可用：'+x.message):'⚪ 未检测'}},{title:'适配器',key:'adapter'},{title:'启用',key:'enabled',render:r=>r.enabled?'是':'否'},{title:'备注',key:'notes'},{title:'操作',key:'actions',render:r=>h(NSpace,{},()=>[h(NButton,{size:'small',onClick:()=>testSource(r)},()=> '测试'),h(NButton,{size:'small',onClick:()=>edit(r)},()=> '编辑'),h(NButton,{size:'small',type:'error',onClick:()=>remove(r)},()=> '删除')])}]
onMounted(()=>{load();loadInterval()})
</script>